// the caller's membership + admin/owner role before calling this.
func (q *Queries) UpdateTenantName(ctx context.Context, arg UpdateTenantNameParams) (Tenant, error) {
	row := q.db.QueryRow(ctx, updateTenantName, arg.ID, arg.Name)
	var i Tenant
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Slug,
		&i.Plan,
		&i.PlanStatus,
		&i.PlanOverrides,
		&i.GraceUntil,
		&i.BillingProvider,
		&i.ProviderCustomerID,
		&i.ProviderSubscriptionID,
		&i.CurrentPeriodEnd,
		&i.CompReason,
		&i.SuspendedAt,
		&i.SuspendedReason,
		&i.CancelAtPeriodEnd,
		&i.DeletedAt,
		&i.PurgeStartedAt,
		&i.AssistantEnabledAt,
		&i.AssistantPausedAt,
		&i.AssistantPausedReason,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
